    unimplemented!()
}

async fn get_audio_url(api_key: &str, api_secret: &str, text: String) -> String {
    let client = Client::new();
    let res = client
        .post("https://api.elevenlabs.io/v1/text-to-speech")
        .header("Authorization", format!("Bearer {}", api_key))
        .header("Content-Type", "application/json")
        .body(json!({
            "text": text,
            "voice": "EnglishUS",
            "format": "mp3",
        }))
        .send()
        .await
        .unwrap();

    let audio_url = res.json::<AudioUrl>().await.unwrap().url;
    audio_url
}

async fn download_audio_file(url: String) -> String {
    let client = Client::new();
    let res = client.get(url).send().await.unwrap();
    let audio_file = res.bytes().await.unwrap();
    audio_file.to_string()
}

struct AudioUrl {
    url: String,
}
```
