```jsx
import React, { useState } from 'react';
import { View, Text, TextInput, Button, FlatList } from 'react-native';

const DreamJournalApp = () => {
  const [dream, setDream] = useState('');
  const [dreams, setDreams] = useState([]);

  const handleSaveDream = () => {
    const newDream = { id: Date.now(), dream };
    setDreams([...dreams, newDream]);
    setDream('');
  };

  const handleDeleteDream = (id) => {
    setDreams(dreams.filter((dream) => dream.id !== id));
  };

  return (
    <View>
      <Text>Dream Journal</Text>
      <TextInput
        value={dream}
        onChangeText={(text) => setDream(text)}
        placeholder="Enter your dream"
        style={{ height: 40, borderColor: 'gray', borderWidth: 1 }}
      />
      <Button title="Save Dream" onPress={handleSaveDream} />
      <FlatList
        data={dreams}
        renderItem={({ item }) => (
          <View>
            <Text>{item.dream}</Text>
            <Button title="Delete" onPress={() => handleDeleteDream(item.id)} />
          </View>
        )}
        keyExtractor={(item) => item.id.toString()}
      />
    </View>
  );
};

export default DreamJournalApp;
